BattleEditor::BattleEditor(BattleProcessor& p):AudioProcessorEditor(p),processor(p){setSize(1120,800);setResizable(true,true);setResizeLimits(1000,760,1600,1100);setWantsKeyboardFocus(true);
 for(int i=0;i<4;++i){addAndMakeVisible(picks[size_t(i)]);picks[size_t(i)].setButtonText("PICK "+juce::String(battle::mcs[size_t(i)].name));picks[size_t(i)].onClick=[this,i]{processor.home=i;int a=opponent.getSelectedId()-1;if(a==i){opponent.setSelectedId((i+1)%4+1);}repaint();};picks[size_t(i)].setWantsKeyboardFocus(false);opponent.addItem(battle::mcs[size_t(i)].name,i+1);}
 addAndMakeVisible(opponent);addAndMakeVisible(difficulty);opponent.setSelectedId(p.away.load()+1);opponent.onChange=[this]{processor.away=opponent.getSelectedId()-1;};difficulty.addItem("ROOKIE / relaxed chart",1);difficulty.addItem("BATTLE / eighth-note streaks",2);difficulty.addItem("HEADLINER / dense chart",3);difficulty.setSelectedId(p.difficulty.load()+1);difficulty.onChange=[this]{processor.difficulty=difficulty.getSelectedId()-1;};
 for(auto* b:{&start,&back,&pause}){addAndMakeVisible(*b);b->setWantsKeyboardFocus(false);}start.onClick=[this]{startBattle();};back.onClick=[this]{processor.stop();menu=true;syncVisibility();};pause.onClick=[this]{processor.pause(!processor.isPaused());pause.setButtonText(processor.isPaused()?"RESUME":"PAUSE");grabKeyboardFocus();};
 addAndMakeVisible(vocals);vocals.setToggleState(p.vocals.load(),juce::dontSendNotification);vocals.setWantsKeyboardFocus(false);vocals.onClick=[this]{processor.vocals=vocals.getToggleState();};addAndMakeVisible(volume);volume.setSliderStyle(juce::Slider::LinearHorizontal);volume.setTextBoxStyle(juce::Slider::TextBoxRight,false,45,22);volume.setRange(0,1,.01);volume.setValue(p.volume.load());volume.onValueChange=[this]{processor.volume=float(volume.getValue());};syncVisibility();startTimerHz(120);
}
void BattleEditor::startBattle(){if(processor.home.load()==processor.away.load()){processor.away=(processor.home.load()+1)%4;opponent.setSelectedId(processor.away.load()+1);}game.start(processor.home.load(),processor.away.load(),processor.difficulty.load(),unsigned(juce::Time::getMillisecondCounter()));held.fill(false);menu=false;lastCombo=0;processor.begin();pause.setButtonText("PAUSE");syncVisibility();grabKeyboardFocus();}
void BattleEditor::syncVisibility(){for(auto& p:picks)p.setVisible(menu);start.setVisible(menu);opponent.setVisible(menu);difficulty.setVisible(menu);back.setVisible(!menu);pause.setVisible(!menu);resized();repaint();}
void BattleEditor::resized(){int w=getWidth(),h=getHeight();int card=(w-100)/4;for(int i=0;i<4;++i)picks[size_t(i)].setBounds(30+i*(card+13),h-210,card-8,34);opponent.setBounds(30,h-125,260,34);difficulty.setBounds(310,h-125,320,34);start.setBounds(w-285,h-130,255,45);back.setBounds(20,14,130,30);pause.setBounds(162,14,90,30);vocals.setBounds(25,h-45,100,26);volume.setBounds(w-230,h-44,200,25);}
void BattleEditor::press(int lane){if(menu||processor.isPaused()||game.finished)return;int before=game.hits[0];game.press(lane,processor.battleTime());if(game.hits[0]>before){processor.vocalGain=1;processor.cue();}else if(game.activeSide()==0)processor.vocalGain=.4f;repaint();}
bool BattleEditor::keyPressed(const juce::KeyPress& k){if(menu)return false;int code=k.getKeyCode();for(int lane=0;lane<4;++lane)if(code==keys[lane]){if(!held[size_t(lane)]){held[size_t(lane)]=true;press(lane);}return true;}if(code=='P'||code==juce::KeyPress::escapeKey){processor.pause(!processor.isPaused());pause.setButtonText(processor.isPaused()?"RESUME":"PAUSE");return true;}return code==juce::KeyPress::spaceKey;}
bool BattleEditor::keyStateChanged(bool){if(menu)return false;for(int lane=0;lane<4;++lane){bool down=juce::KeyPress::isKeyCurrentlyDown(keys[lane]);if(!down)held[size_t(lane)]=false;else if(!held[size_t(lane)]){held[size_t(lane)]=true;press(lane);}}return true;}
void BattleEditor::focusLost(FocusChangeType){if(!menu&&!game.finished){processor.pause(true);pause.setButtonText("RESUME");held.fill(false);}}
void BattleEditor::mouseDown(const juce::MouseEvent&){if(!menu)grabKeyboardFocus();}
void BattleEditor::timerCallback(){if(!menu&&!processor.isPaused()&&!game.finished){int misses=game.misses[0];game.update(processor.battleTime());if(game.misses[0]>misses)processor.vocalGain=.4f;if(game.combo[0]>lastCombo&&game.combo[0]%8==0)processor.cue();lastCombo=game.combo[0];if(game.finished)processor.stop();}repaint();}
