 g.setColour(col(0xeac765));g.drawEllipse(x-13*s,y-19*s+bob,28*s,30*s,2*s);g.setColour(skin);g.fillRoundedRectangle(x-48*s,y-8*s+bob,17*s,50*s,6*s);float handY=active?y-29*s+bob:y+20*s;g.drawLine(x+35*s,y-7*s+bob,x+49*s,handY,12*s);g.setColour(col(0x232936));g.drawLine(x+49*s,handY,x+58*s,handY-17*s,5*s);g.setColour(col(0xd7dce4));g.fillEllipse(x+53*s,handY-24*s,12*s,12*s);g.setColour(juce::Colours::black);g.fillEllipse(x-11*s,y-45*s+bob,4*s,4*s);g.fillEllipse(x+8*s,y-45*s+bob,4*s,4*s);
