 g.setColour(col(0x252039));g.fillRect(x,y+h*.62f,w,h*.38f);g.setColour(col(0xa366ff));g.fillRect(x,y+h*.62f,w,2.f);text(g,"THE UNDERGROUND",{x+w*.26f,y+16,w*.48f,30},22,col(0xbba3e8));
 int hm=preview?processor.home.load():game.home,am=preview?processor.away.load():game.away;float scale=std::min(1.05f,h/250);rapper(g,x+w*.28f,y+h*.48f,scale,hm,!preview&&game.activeSide()==0,t);rapper(g,x+w*.72f,y+h*.48f,scale,am,!preview&&game.activeSide()==1,t);
 for(int n=0;n<35;++n){float px=x+n*(w/34),py=y+h-15+float(std::sin(t*6+n)*5);g.setColour(col(0x080912));g.fillEllipse(px-9,py-8,18,18);g.fillRoundedRectangle(px-15,py+5,30,25,6);if(n%5==0){g.drawLine(px-11,py+13,px-22,py-18,5);g.drawLine(px+11,py+13,px+23,py-12,5);}}
