 float top=454,bottom=h-90,topW=170,bottomW=480,cx=w*.5f;juce::Path highway;highway.startNewSubPath(cx-topW/2,top);highway.lineTo(cx+topW/2,top);highway.lineTo(cx+bottomW/2,bottom+12);highway.lineTo(cx-bottomW/2,bottom+12);highway.closeSubPath();g.setColour(col(0x151b2b));g.fillPath(highway);
